import fs from 'fs/promises'
import path from 'path'

const DB_PATH = path.join(process.cwd(), 'notification-db.json')

export async function getPreference(): Promise<boolean> {
  try {
    const data = await fs.readFile(DB_PATH, 'utf-8')
    return JSON.parse(data).notificationsEnabled
  } catch (error) {
    // Default to true if file doesn't exist
    return true
  }
}

export async function setPreference(enabled: boolean): Promise<void> {
  await fs.writeFile(DB_PATH, JSON.stringify({ notificationsEnabled: enabled }))
}

