args.content:
import { toggleNotifications } from '../actions'
import { getPreference } from '../../lib/db'

export default async function NotificationPage() {
  const notificationsEnabled = await getPreference()

  return (
    <div className="p-8 max-w-md mx-auto">
      <h1 className="text-2xl font-bold mb-6">Notification Settings</h1>

      <div className="flex items-center justify-between border p-4 rounded-lg bg-white shadow-sm">
        <div>
          <h2 className="font-semibold text-gray-900">Push Notifications</h2>
          <p className="text-sm text-gray-500">Enable or disable instant alerts</p>
        </div>

        <form action={toggleNotifications}>
          <button 
            type="submit"
            className={`px-4 py-2 rounded-md font-medium transition-colors ${
              notificationsEnabled 
                ? 'bg-blue-600 text-white hover:bg-blue-700' 
                : 'bg-gray-200 text-gray-800 hover:bg-gray-300'
            }`}
          >
            {notificationsEnabled ? 'Enabled' : 'Disabled'}
          </button>
        </form>
      </div>

      <p className="mt-6 text-sm text-gray-500 text-center">
        Current system status: <strong className={notificationsEnabled ? 'text-blue-600' : 'text-gray-600'}>
          {notificationsEnabled ? 'ACTIVE' : 'INACTIVE'}
        </strong>
      </p>
    </div>
  )
}

